/// <summary>
/// Event handler class for <t>InventItemBarcode</t>
/// </summary>
public final class METInventItemBarcodeTableEventHandler
{
}

Method.Source:
    /// <summary>
    ///Event handler for insert method 
    /// </summary>
    /// <param name="sender"><t>InventItemBarcode</t> buffer</param>
    /// <param name="e">Table event</param>
    [DataEventHandler(tableStr(InventItemBarcode), DataEventType::Inserting)]
    public static void InventItemBarcode_onInserting(Common sender, DataEventArgs e)
    {
        InventItemBarcode   inventItemBarcodeCur, inventItemBarcodeDefault;

        inventItemBarcodeCur = sender as InventItemBarcode;

        
        select firstonly RecId from inventItemBarcodeDefault
            where inventItemBarcodeDefault.itemId == inventItemBarcodeCur.itemId
                && inventItemBarcodeDefault.UnitID == inventItemBarcodeCur.UnitID
                && inventItemBarcodeDefault.METDefault == NoYes::Yes;

        if(inventItemBarcodeDefault.RecId && inventItemBarcodeCur.METDefault)
        {
            InventItemBarcode::METUpdateDefaultForItemBarcode(inventItemBarcodeCur);
        }
        else if(!inventItemBarcodeDefault.RecId)
        {
            inventItemBarcodeCur.METDefault = NoYes::Yes;
        }
    }

    /// <summary>
    ///Event handler for update method
    /// </summary>
    /// <param name="sender"><t>InventItemBarcode</t> buffer</param>
    /// <param name="e">Table event</param>
    [DataEventHandler(tableStr(InventItemBarcode), DataEventType::Updating)]
    public static void InventItemBarcode_onUpdating(Common sender, DataEventArgs e)
    {
        InventItemBarcode   inventItemBarcodeCur, inventItemBarcodeOrig, inventItemBarcodeDefault;

        inventItemBarcodeCur = sender as InventItemBarcode;
        inventItemBarcodeOrig = inventItemBarcodeCur.orig();

        if(inventItemBarcodeCur.METDefault && (inventItemBarcodeCur.METDefault != inventItemBarcodeOrig.METDefault))
        {
        
            select firstonly RecId from inventItemBarcodeDefault
                where inventItemBarcodeDefault.itemId == inventItemBarcodeCur.itemId
                    && inventItemBarcodeDefault.UnitID == inventItemBarcodeCur.UnitID
                    && inventItemBarcodeDefault.METDefault == NoYes::Yes;

            if(inventItemBarcodeDefault.RecId && inventItemBarcodeCur.METDefault)
            {
                InventItemBarcode::METUpdateDefaultForItemBarcode(inventItemBarcodeCur);
            }
        }
    }
